-- Creates the dbo.Sales table used by the app and loads the same rows as data/sample_sales.csv.
-- Run this in the Azure portal Query editor (or Azure Data Studio / SSMS) against YOUR OWN database.
-- Safe to re-run: it drops and recreates the table.

IF OBJECT_ID('dbo.Sales', 'U') IS NOT NULL DROP TABLE dbo.Sales;

CREATE TABLE dbo.Sales (
    order_id      VARCHAR(20)    NOT NULL PRIMARY KEY,
    order_date    DATE           NOT NULL,
    region        VARCHAR(20)    NOT NULL,
    city          VARCHAR(50)    NOT NULL,
    category      VARCHAR(50)    NOT NULL,
    product       NVARCHAR(100)  NOT NULL,
    channel       VARCHAR(20)    NOT NULL,
    quantity      INT            NOT NULL CHECK (quantity > 0),
    unit_price    DECIMAL(10,2)  NOT NULL,
    discount_pct  INT            NOT NULL DEFAULT 0,
    total_amount  DECIMAL(12,2)  NOT NULL
);




-- Quick check: should return 240
SELECT COUNT(*) AS row_count FROM dbo.Sales;
